package com.hmdp.ai.api.tool;
import com.hmdp.ai.api.security.RequireAiPermission;import com.hmdp.ai.application.dto.PageResponse;import com.hmdp.ai.application.dto.tool.CreateToolRequest;import com.hmdp.ai.application.dto.tool.ToolResponse;import com.hmdp.ai.application.tool.ToolApplicationService;import com.hmdp.ai.domain.security.AiPermission;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import javax.validation.Valid;import javax.validation.constraints.*;
@RestController @RequestMapping("/api/v1/tools") @RequireAiPermission(AiPermission.TOOL_MANAGE) @Validated public class ToolController {private final ToolApplicationService tools;public ToolController(ToolApplicationService tools){this.tools=tools;}@PostMapping public ToolResponse create(@Valid @RequestBody CreateToolRequest request){return tools.create(request);}@GetMapping public PageResponse<ToolResponse> list(@RequestParam(defaultValue="1") @Min(1) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return tools.list(page,size);}}
